// This file is generated by AI.

// 选项卡顺序与拖拽落点规则测试。
//
// 这些规则决定了"打开新选项卡放在哪、关闭后跳到哪、拖拽后序列是什么、竖线画在哪",
// 一旦被破坏就会出现选项卡跳位、多个选中、落点指示错位这类观感问题。

import { describe, expect, it } from 'vitest';

import { dropIndicator, dropSlot, slotToIndex, type TabBox } from '../src/tabs/dnd';
import { makeDiffTab, makeNovelTab, makeSceneTab, makeWorkbenchTab } from '../src/tabs/model';
import { closeTab, insertTab, moveTab, removeTabsByKind } from '../src/tabs/order';

const sceneA = makeSceneTab('C:/p/game/scene/a.txt', 'a.txt');
const sceneB = makeSceneTab('C:/p/game/scene/b.txt', 'b.txt');
const diff = makeDiffTab({ file: 'game/scene/a.txt', title: 'a.txt (更改)', diffKind: 'unstaged' });
const workbench = makeWorkbenchTab();

describe('insertTab', () => {
  it('新选项卡插入在活动选项卡之后', () => {
    const first = insertTab([], sceneA, null);
    expect(first.tabs.map((tab) => tab.id)).toEqual([sceneA.id]);
    expect(first.activeId).toBe(sceneA.id);

    const second = insertTab(first.tabs, workbench, first.activeId);
    // 工作台插在场景 A 之后, 而不是追加到末尾之外的某个"同类"区域
    expect(second.tabs.map((tab) => tab.kind)).toEqual(['scene', 'voice-workbench']);
    expect(second.activeId).toBe(workbench.id);
  });

  it('在中间插入时保持左右两侧的原有顺序', () => {
    let state = insertTab([], sceneA, null);
    state = insertTab(state.tabs, sceneB, state.activeId);
    state = insertTab(state.tabs, diff, sceneA.id);
    expect(state.tabs.map((tab) => tab.id)).toEqual([sceneA.id, diff.id, sceneB.id]);
  });

  it('重复打开同一选项卡只激活, 不新增也不改变位置', () => {
    let state = insertTab([], sceneA, null);
    state = insertTab(state.tabs, sceneB, state.activeId);
    const again = insertTab(state.tabs, makeSceneTab(sceneA.path, 'a.txt'), sceneB.id);
    expect(again.tabs.map((tab) => tab.id)).toEqual([sceneA.id, sceneB.id]);
    expect(again.activeId).toBe(sceneA.id);
  });

  it('活动项已不存在时追加到末尾', () => {
    const state = insertTab([sceneA], sceneB, 'missing-id');
    expect(state.tabs.map((tab) => tab.id)).toEqual([sceneA.id, sceneB.id]);
  });
});

describe('closeTab', () => {
  const tabs = [sceneA, workbench, diff, sceneB];

  it('关闭非活动项不影响活动项', () => {
    const result = closeTab(tabs, diff.id, sceneA.id);
    expect(result.tabs.map((tab) => tab.id)).toEqual([sceneA.id, workbench.id, sceneB.id]);
    expect(result.activeId).toBe(sceneA.id);
  });

  it('关闭活动项后激活右侧邻居', () => {
    const result = closeTab(tabs, workbench.id, workbench.id);
    expect(result.activeId).toBe(diff.id);
  });

  it('关闭最右侧活动项后回退到左侧邻居', () => {
    const result = closeTab(tabs, sceneB.id, sceneB.id);
    expect(result.activeId).toBe(diff.id);
  });

  it('关闭最后一个选项卡后没有活动项', () => {
    const result = closeTab([sceneA], sceneA.id, sceneA.id);
    expect(result.tabs).toEqual([]);
    expect(result.activeId).toBeNull();
  });

  it('关闭不存在的 id 不改变任何状态', () => {
    const result = closeTab(tabs, 'nope', sceneA.id);
    expect(result.tabs).toBe(tabs);
    expect(result.activeId).toBe(sceneA.id);
  });

  it('不同种类的选项卡可以互相成为邻居 (关闭后不会跳回同类)', () => {
    const result = closeTab([sceneA, diff, workbench], sceneA.id, sceneA.id);
    expect(result.activeId).toBe(diff.id);
  });
});

describe('moveTab', () => {
  const tabs = [sceneA, sceneB, diff, workbench];

  it('可以把任意选项卡拖到任意位置 (不受种类限制)', () => {
    const moved = moveTab(tabs, workbench.id, 0);
    expect(moved.map((tab) => tab.kind)).toEqual(['voice-workbench', 'scene', 'scene', 'diff']);
  });

  it('向后拖动时落在目标槽位', () => {
    const moved = moveTab(tabs, sceneA.id, 2);
    expect(moved.map((tab) => tab.id)).toEqual([sceneB.id, diff.id, sceneA.id, workbench.id]);
  });

  it('越界的目标下标会被夹取', () => {
    expect(moveTab(tabs, sceneA.id, 99).map((tab) => tab.id)).toEqual([sceneB.id, diff.id, workbench.id, sceneA.id]);
    expect(moveTab(tabs, workbench.id, -5).map((tab) => tab.id)).toEqual([workbench.id, sceneA.id, sceneB.id, diff.id]);
  });

  it('拖回原位不产生新数组', () => {
    expect(moveTab(tabs, sceneB.id, 1)).toBe(tabs);
  });

  it('不存在的 id 不改变序列', () => {
    expect(moveTab(tabs, 'nope', 0)).toBe(tabs);
  });
});

describe('removeTabsByKind', () => {
  it('按种类批量清理 (退出项目时使用)', () => {
    const remaining = removeTabsByKind([sceneA, makeNovelTab(1), diff, workbench], 'novel');
    expect(remaining.map((tab) => tab.kind)).toEqual(['scene', 'diff', 'voice-workbench']);
  });
});

describe('拖拽落点', () => {
  // 三个宽度 100 的选项卡: [0,100) [100,200) [200,300)
  const tabs = [sceneA, diff, sceneB];
  const boxes: TabBox[] = [
    { id: sceneA.id, left: 0, width: 100 },
    { id: diff.id, left: 100, width: 100 },
    { id: sceneB.id, left: 200, width: 100 },
  ];

  it('按中点判定插入缝隙', () => {
    expect(dropSlot(boxes, 0)).toBe(0);
    expect(dropSlot(boxes, 49)).toBe(0);
    // 越过第一个选项卡中点 -> 落在它之后
    expect(dropSlot(boxes, 51)).toBe(1);
    expect(dropSlot(boxes, 149)).toBe(1);
    expect(dropSlot(boxes, 151)).toBe(2);
  });

  it('拖到最右端得到"末尾缝隙", 而不是最后一个选项卡之前', () => {
    expect(dropSlot(boxes, 280)).toBe(3);
    expect(dropSlot(boxes, 1000)).toBe(3);
    // 关键: 末尾缝隙应产生"画在最后一个选项卡右侧"的指示
    expect(dropIndicator(tabs, sceneA.id, 3)).toEqual({ id: sceneB.id, side: 'after' });
  });

  it('越过最后一个选项卡中点即视为落到末尾', () => {
    // 最后一个选项卡中点 250; 之前仍算"插到它前面"
    expect(dropSlot(boxes, 249)).toBe(2);
    expect(dropIndicator(tabs, sceneA.id, 2)).toEqual({ id: sceneB.id, side: 'before' });
  });

  it('落到其它选项卡之前时画在左侧', () => {
    expect(dropIndicator(tabs, sceneB.id, 1)).toEqual({ id: diff.id, side: 'before' });
  });

  it('落点等同原位时不显示指示', () => {
    expect(dropIndicator(tabs, sceneA.id, 0)).toBeNull();
    expect(dropIndicator(tabs, sceneA.id, 1)).toBeNull();
    expect(dropIndicator(tabs, diff.id, 2)).toBeNull();
  });

  it('缝隙换算成目标槽位', () => {
    // 把 A 拖到 index 2 之后 (缝隙 3) -> 目标 2
    expect(slotToIndex(tabs, sceneA.id, 3)).toBe(2);
    // 把 C 拖到最前 (缝隙 0) -> 目标 0
    expect(slotToIndex(tabs, sceneB.id, 0)).toBe(0);
    // 原位 -> null
    expect(slotToIndex(tabs, diff.id, 1)).toBeNull();
    expect(slotToIndex(tabs, diff.id, 2)).toBeNull();
  });

  it('落点换算与 moveTab 的组合结果正确', () => {
    const slot = dropSlot(boxes, 1000);
    const target = slotToIndex(tabs, sceneA.id, slot!);
    const moved = moveTab(tabs, sceneA.id, target!);
    expect(moved.map((tab) => tab.id)).toEqual([diff.id, sceneB.id, sceneA.id]);
  });

  it('空序列不产生落点', () => {
    expect(dropSlot([], 50)).toBeNull();
    expect(dropIndicator([], sceneA.id, 0)).toBeNull();
  });
});
